export interface BlockTypeRegistration {
  type: string;
  view: Component<BlockViewProps>;
  /** Optional authored defaults, independent of mounted application state. */
  create?: () => ExistingBlockDto;
  capabilities: string[];
  aliases?: string[];
  slots?: SlotSpec[];
}

export interface PropertyTypeDefinition {
  readonly semantic?:SemanticAuthoringDescriptor;
  readonly type:string;
  readonly renderers:readonly RendererBinding[];
  readonly stateOrder?:readonly string[];
  readonly states?:Readonly<Record<string,Readonly<Record<string,EffectParams>>>>;
  readonly events?:Partial<Record<CaretTransition,readonly string[]>>;
}

export interface SemanticAuthoringDescriptor {
  readonly purpose:string; readonly attributes:readonly string[];
  readonly ai:'authorable'|'inert'; readonly rendering:string; readonly validation:string;
}

export interface StandoffStyleSchema {
  semantic?:SemanticAuthoringDescriptor;
  cell?: JSX.CSSProperties;
  valueStyle?: "color" | "background-color";
  svg?: SvgStyle;
  cellEffect?: true;
  regionEffect?: true;
  noiseEffect?: true;
  projection?: "show-hide";
  deferred?: "range-wrapper" | "animation-plugin" | "embedded-document";
}

export interface TimerPayload {
  durationSeconds: number;
  mode: TimerMode;
  runningUntil?: number;
  remainingMilliseconds?: number;
}

export interface ObjectState {
  version: 1; scene: string; view: ViewAngles; autoRotate: boolean; lighting: Lighting;
  settings: Record<string, unknown>;
}

export type ScreenSettings = {
  version: 1;
  columns: 40 | 80;
  rows: 24;
  scroll: boolean;
  layout: "spatial" | "prose";
  tab: 4 | 8;
  glyphEncoding: typeof GLYPH_ENCODING;
};

export type AcademicAnchor =
  | {
      version: 1;
      snapshotId: string;
      kind: 'ocr-page';
      pageId: string;
      width: number;
      height: number;
      points: number[][];
    }
  | { version: 1; snapshotId: string; kind: 'epub-fragment'; path: string; fragment: string };

export interface AcademicCapture {
  version: 1;
  kind: 'deterministic';
  snapshotId: string;
  resourceId: string;
  source: string;
  endpoint: string;
  retrievedAt: string;
  asset: ManagedAssetReference;
  format: AcademicFormat;
  projection: AcademicProjection;
  identity?: AcademicIdentifier;
  assets?: ManagedAssetReference[];
}

export interface WebCapture {
  version: 1;
  snapshotId: string;
  source: string;
  capturedAt: string;
  asset: ManagedAssetReference;
  projection: WebProjection;
}
